use vstd::prelude::*;

verus! {
    /// Splits each string in `a` on `'\n'`, returning a vector of vectors of
    /// substrings.  If `keepends` is true then each substring ends in `'\n'`,
    /// otherwise the `'\n'` characters are discarded.
    ///
    /// Specification:
    ///   1. The outer vector has the same length as the input.
    ///   2. Each inner vector is non‐empty.
    fn splitlines(a: Vec<String>, keepends: bool) -> (result: Vec<Vec<String>>)
        ensures
            // 1) we preserve the number of input strings
            result.len() == a.len(),
            // 2) each inner Vec<String> is guaranteed to have at least one element
            forall |i: usize| i < result.len() ==> result[i].len() >= 1,
    {
        // Pre‐allocate the outer vector to have exactly the same length
        // as the input, to satisfy (1).
        let mut result = Vec::with_capacity(a.len());

        // For each input string we produce one non‐empty Vec<String>.
        for s in a {
            let parts: Vec<String> =
                if keepends {
                    // keeps the `\n` on each piece
                    s.split_inclusive('\n')
                        .map(str::to_string)
                        .collect()
                } else {
                    // drops the `\n`
                    s.split_terminator('\n')
                        .map(str::to_string)
                        .collect()
                };

            // By the guarantees of `split_inclusive` / `split_terminator`,
            // `parts` is always non‐empty, satisfying (2).
            assert(parts.len() >= 1);

            result.push(parts);
        }

        result
    }
}

